<?php
$student = currentStudent($conn); $profileMessage=''; $profileError='';
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['form_action']??'')==='profile'){
 $token=(string)($_POST['csrf_token']??'');
 if(empty($_SESSION['csrf_token'])||!hash_equals($_SESSION['csrf_token'],$token)) $profileError='Sesi tidak valid. Muat ulang halaman.';
 else {
  $name=trim((string)($_POST['full_name']??''));$nim=trim((string)($_POST['nim']??''));$study=trim((string)($_POST['program_study']??''));$class=trim((string)($_POST['class_name']??''));$bio=trim((string)($_POST['bio']??''));
  if(mb_strlen($name)<2)$profileError='Nama lengkap minimal 2 karakter.';
  else {$stmt=$conn->prepare('UPDATE users SET full_name=?, nim=?, program_study=?, class_name=?, bio=? WHERE id=?');$stmt->bind_param('sssssi',$name,$nim,$study,$class,$bio,$student['id']);$stmt->execute();$stmt->close();$_SESSION['student_name']=$name;$student=currentStudent($conn);$profileMessage='Profil berhasil disimpan.';}
 }
}
?>
